# Let's write a Go file to test parsing
cat <<'GO' > /tmp/parse_test.go
package main

import (
	"encoding/xml"
	"fmt"
	"os"
	"strings"
)

type WSDL struct {
	XMLName xml.Name `xml:"definitions"`
	TargetNamespace string `xml:"targetNamespace,attr"`
	Types Types `xml:"types"`
	Messages []Message `xml:"message"`
}

type Types struct {
	Schemas []Schema `xml:"schema"`
}

type Schema struct {
	XMLName xml.Name `xml:"schema"`
	TargetNamespace string `xml:"targetNamespace,attr"`
	Elements []Element `xml:"element"`
	ComplexTypes []ComplexType `xml:"complexType"`
	SimpleTypes []SimpleType `xml:"simpleType"`
}

type Element struct {
	XMLName xml.Name `xml:"element"`
	Name string `xml:"name,attr"`
	Type string `xml:"type,attr"`
	ComplexType *ComplexType `xml:"complexType"`
	SimpleType *SimpleType `xml:"simpleType"`
}

type ComplexType struct {
	XMLName xml.Name `xml:"complexType"`
	Name string `xml:"name,attr"`
	Sequence *Sequence `xml:"sequence"`
	All *All `xml:"all"`
}

type Sequence struct {
	Elements []Element `xml:"element"`
}

type All struct {
	Elements []Element `xml:"element"`
}

type SimpleType struct {
	XMLName xml.Name `xml:"simpleType"`
	Name string `xml:"name,attr"`
	Restriction *Restriction `xml:"restriction"`
}

type Restriction struct {
	Base string `xml:"base,attr"`
	Enumerations []Enumeration `xml:"enumeration"`
}

type Enumeration struct {
	Value string `xml:"value,attr"`
}

type Message struct {
	XMLName xml.Name `xml:"message"`
	Name string `xml:"name,attr"`
	Parts []Part `xml:"part"`
}

type Part struct {
	Name string `xml:"name,attr"`
	Element string `xml:"element,attr"`
	Type string `xml:"type,attr"`
}

func main(){
	data, _ := os.ReadFile(os.Args[1])
	var wsdl WSDL
	err := xml.Unmarshal(data, &wsdl)
	if err != nil {
		fmt.Println("unmarshal error:", err)
		// Try with decoder and skip namespaces?
	}
	fmt.Printf("TargetNS: %s\n", wsdl.TargetNamespace)
	fmt.Printf("Schemas: %d\n", len(wsdl.Types.Schemas))
	for i,s := range wsdl.Types.Schemas {
		fmt.Printf(" Schema %d targetNS=%s elements=%d complex=%d simple=%d\n", i, s.TargetNamespace, len(s.Elements), len(s.ComplexTypes), len(s.SimpleTypes))
		for _, e := range s.Elements {
			fmt.Printf("  Element %s type=%s hasComplex=%v hasSimple=%v\n", e.Name, e.Type, e.ComplexType!=nil, e.SimpleType!=nil)
			if e.ComplexType != nil && e.ComplexType.Sequence != nil {
				fmt.Printf("    Seq elements: %d\n", len(e.ComplexType.Sequence.Elements))
				for _, se := range e.ComplexType.Sequence.Elements {
					fmt.Printf("      seq elem %s type=%s\n", se.Name, se.Type)
				}
			}
			if e.SimpleType != nil && e.SimpleType.Restriction != nil {
				fmt.Printf("    Simple restriction base=%s enums=%d\n", e.SimpleType.Restriction.Base, len(e.SimpleType.Restriction.Enumerations))
			}
		}
		for _, ct := range s.ComplexTypes {
			fmt.Printf("  ComplexType %s\n", ct.Name)
			if ct.Sequence != nil {
				fmt.Printf("    Seq %d\n", len(ct.Sequence.Elements))
			}
		}
		for _, st := range s.SimpleTypes {
			fmt.Printf("  SimpleType %s base=%s enums=%d\n", st.Name, st.Restriction.Base, len(st.Restriction.Enumerations))
		}
	}
	fmt.Printf("Messages %d\n", len(wsdl.Messages))
	for _, m := range wsdl.Messages {
		fmt.Printf(" Message %s parts=%d\n", m.Name, len(m.Parts))
		for _, p := range m.Parts {
			fmt.Printf("  Part %s elem=%s type=%s\n", p.Name, p.Element, p.Type)
		}
	}
	// check raw file content for import
	if strings.Contains(string(data), "schemaLocation") {
		fmt.Println("contains schemaLocation")
	}
}
GO
go run /tmp/parse_test.go assets/test.wsdl
echo "---"
go run /tmp/parse_test.go assets/stock.wsdl
echo "---"
go run /tmp/parse_test.go assets/mnb-exchange.wsdl
"}

